"""launcher/xbox_pc/xml_lite: the re-only reader for Xbox PC manifests."""
from __future__ import annotations

import ast
import sys
from pathlib import Path

import pytest

from unifideck.launcher.xbox_pc import xml_lite

_REPO = Path(__file__).resolve().parents[2]

# A trimmed MicrosoftGame.config shape (GDK): default namespace, comments,
# a processing instruction and attributes in both quote styles.
_MANIFEST = """﻿<?xml version="1.0" encoding="utf-8"?>
<!-- generated by the GDK -->
<Game configVersion="1" xmlns="http://schemas.microsoft.com/gdk/2020">
  <Identity Name="Studio.Game" Publisher='CN=Studio' Version="1.0.5.0"/>
  <ExecutableList>
    <Executable Name="bin\\Game.exe" Id="Game"/>
  </ExecutableList>
  <ShellVisuals DefaultDisplayName="Tom &amp; Jerry &#x2122;"/>
  <StoreId>9PK087LNGJC5</StoreId>
  <Resources><Resource Language="en-US"/><Resource Language="fr-FR"/></Resources>
</Game>
"""


def test_reads_elements_attributes_and_text() -> None:
    root = xml_lite.fromstring(_MANIFEST.lstrip("﻿"))
    assert root.tag == "Game"
    tags = [node.tag for node in root.iter()]
    assert tags[:4] == ["Game", "Identity", "ExecutableList", "Executable"]
    identity = root.find("Identity")
    assert identity is not None and identity.get("Version") == "1.0.5.0"
    assert identity.get("Publisher") == "CN=Studio"
    visuals = root.find("ShellVisuals")
    assert visuals is not None and visuals.get("DefaultDisplayName") == "Tom & Jerry ™"
    store = root.find("StoreId")
    assert store is not None and store.text == "9PK087LNGJC5"
    assert [n.get("Language") for n in root.iter() if n.tag == "Resource"] == ["en-US", "fr-FR"]
    assert root.get("missing", "x") == "x"


def test_parse_file_handles_utf8_bom_and_utf16(tmp_path: Path) -> None:
    utf8 = tmp_path / "a.config"
    utf8.write_bytes(_MANIFEST.encode("utf-8"))
    assert xml_lite.parse_file(utf8).tag == "Game"
    utf16 = tmp_path / "b.config"
    utf16.write_bytes(_MANIFEST.lstrip("﻿").encode("utf-16"))
    assert xml_lite.parse_file(utf16).find("StoreId") is not None


def test_prefixes_cdata_and_nested_text() -> None:
    root = xml_lite.fromstring(
        "<r:Reply xmlns:r='urn:x'><r:HResult>0</r:HResult>"
        "<Note><![CDATA[a < b]]> &lt;ok&gt;</Note></r:Reply>"
    )
    assert root.tag == "Reply"
    hresult = root.find("HResult")
    assert hresult is not None and hresult.text == "0"
    note = root.find("Note")
    assert note is not None and note.text == "a < b <ok>"


@pytest.mark.parametrize(
    "text",
    [
        "",
        "plain text",
        "<a>",
        "<a></b>",
        "<a/><b/>",
        "<a>&nope;</a>",
        "<a>bare & amp</a>",
        "<a>&#xFFFFFFFF;</a>",
        "<a x='1' <b/></a>",
        '<!DOCTYPE a [<!ENTITY e "boom">]><a>&e;</a>',
        "text<a/>",
    ],
)
def test_rejects_malformed_or_unsafe_input(text: str) -> None:
    with pytest.raises(xml_lite.ParseError):
        xml_lite.fromstring(text)


def test_parse_error_is_a_value_error() -> None:
    # update_service catches ValueError for both int() and parse failures.
    assert issubclass(xml_lite.ParseError, ValueError)


def test_parse_file_rejects_undecodable_bytes(tmp_path: Path) -> None:
    bad = tmp_path / "bad.config"
    bad.write_bytes(b"<a>\x80</a>")
    with pytest.raises(xml_lite.ParseError):
        xml_lite.parse_file(bad)


def _imports(path: Path) -> set[str]:
    found: set[str] = set()
    for node in ast.walk(ast.parse(path.read_text(encoding="utf-8"))):
        if isinstance(node, ast.Import):
            found.update(alias.name for alias in node.names)
        elif isinstance(node, ast.ImportFrom) and node.level == 0 and node.module:
            found.add(node.module)
    return found


# Stdlib packages that Decky's frozen PluginLoader Python does not ship.
# Importing one from plugin code fails at load time and the whole plugin
# fails to start ("Failed to start Unifideck"), while every test passes on
# a full CPython. Measured against ~/homebrew/services/PluginLoader.
_MISSING_FROM_DECKY_PYTHON = {"xml"}


def test_no_plugin_module_imports_a_package_decky_python_lacks() -> None:
    assert "xml" in sys.stdlib_module_names
    roots = [_REPO / "main.py", *sorted((_REPO / "py_modules" / "unifideck").rglob("*.py"))]
    offenders = sorted(
        f"{path.relative_to(_REPO)}: {name}"
        for path in roots
        for name in _imports(path)
        if name.split(".")[0] in _MISSING_FROM_DECKY_PYTHON
    )
    assert offenders == [], "use launcher/xbox_pc/xml_lite instead:\n" + "\n".join(offenders)
